              @v_plan_end_date = CONVERT(nvarchar(8), DATEADD(SS, (a.PLAN_HORIZON * CASE a.PLAN_HORIZON_UOM WHEN 'SECOND' THEN 1 WHEN 'MINUTE' THEN 60 WHEN 'HOUR' THEN 1440 ELSE 86400 END) - 86400, a.PLAN_START_DTTM), 112)
      FROM    dbo.TH_MST_PLAN  AS a
