      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null


      INSERT INTO SY_FP_PLAN_UTILIZATION_R
            (
              INSTANCE_ID
            , FP_PLAN_ID
            , COMPANY_ID
            , DIVISION_ID
            , SITE_ID
            , PLANT_ID
            , FACTORY_ID
            , EQUIPMENT_ID
            , PLAN_DATE
            , LINE_ID
            , OPERATION_ID
            , WORK_CENTER_ID
            , WORK_TIME
            , OFF_TIME
            , RUN_TIME
            , SETUP_TIME
            , IDLE_TIME
            , CAPACITY_UOM
            , PLAN_QTY
            , INSERT_ID
            , INSERT_TIME
            )
      SELECT 
              fci.MASTER_ID
            , fci.PLAN_ID
            , fci.COMPANY_ID
            , fci.DIVISION_ID
            , fci.SITE_ID
            , fci.PLANT_ID
            , fci.FACTORY_ID
            , fci.resource_id
            , fci.start_date
            , fci.LINE_ID
            , fci.OPERATION_ID
            , fci.WORK_CENTER_ID
            , sum(fci.work_capacity) as work_time
            , sum(fci.off_capacity) AS off_time
            , sum(fci.run_capacity) AS run_time
            , sum(fci.setup_capacity) AS setup_time
            , sum(fci.slack_capacity) AS IDLE_TIME
            , 'MINUTE' AS capacity_uom
            , sum(fci.plan_qty) AS plan_qty
            , @v_proc_name AS insert_id
            , getdate() AS insert_dttm
      FROM 
            (
              SELECT 
                      a.MASTER_ID
                    , a.PLAN_ID
                    , CASE CHARINDEX('^', a.RESOURCE_ID)
                        WHEN 0 THEN a.RESOURCE_ID
                        ELSE substring(a.RESOURCE_ID, 1, CHARINDEX('^', a.RESOURCE_ID) - 1)
                      END AS resource_id
                    , a.RESOURCE_ID AS org_resource_id
                    , CONVERT(date,a.WORK_DATE) AS start_date
                    , round(a.WORK_TIME   / 60, 2) AS work_capacity
                    , round(a.OFF_TIME    / 60, 2) AS off_capacity
                    , round(a.RUN_TIME    / 60, 2) AS run_capacity
                    , round((a.SETUP_TIME - a.OFF_SETUP_TIME)/ 60, 2) AS setup_capacity
                    , round(a.SLACK_TIME  / 60, 2) AS slack_capacity
                    , a.WORK_TIME
                    , a.RUN_TIME
                    , 0 AS plan_qty
                    , isnull(B.RES_ATTB_11,'-') as COMPANY_ID
                    , isnull(B.RES_ATTB_12,'-') as DIVISION_ID
                    , isnull(B.RES_ATTB_13,'-') as SITE_ID
