                    , isnull(B.RES_ATTB_15,'-') as FACTORY_ID
                    , isnull(B.RES_ATTB_17,'-') as LINE_ID
                    , isnull(B.RES_ATTB_18,'-') as OPERATION_ID
                    , isnull(B.RES_ATTB_19,'-') as WORK_CENTER_ID
              FROM 
                      dbo.TH_BUF_OUT_UTILIZATION  AS a
                      INNER JOIN dbo.TH_MST_RESOURCE  AS b
                            ON      a.MASTER_ID = b.MASTER_ID 
