              AND     CAST(CONVERT(nvarchar(8),a.WORK_DATE, 112) AS DATETIME) BETWEEN CAST(CONVERT(nvarchar(8), @v_plan_start_date, 112) AS DATETIME) AND CAST(CONVERT(nvarchar(8), @v_plan_end_date, 112) AS DATETIME)
            )  AS fci
