      INSERT INTO SY_FP_PLAN_UTILIZATION_R
            (
              INSTANCE_ID
            , FP_PLAN_ID
            , COMPANY_ID
            , DIVISION_ID
            , SITE_ID
            , PLANT_ID
            , FACTORY_ID
            , EQUIPMENT_ID
            , PLAN_DATE
            , LINE_ID
            , OPERATION_ID
            , WORK_CENTER_ID
            , WORK_TIME
            , RUN_TIME
            , OFF_TIME
            , SETUP_TIME
            , IDLE_TIME
            , CAPACITY_UOM
            , PLAN_QTY
            , INSERT_ID
            , INSERT_TIME
            )
      SELECT A.MASTER_ID, A.PLAN_ID, 
             A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID,
             A.RESOURCE_ID, A.PLAN_DATE, 
             A.LINE_ID, A.OPERATION_ID, A.WORK_CENTER_ID,
             1440 AS WORK_TIME,
             ROUND(SUM(RUN_TIME) / 60, 2) AS RUN_TIME,
             ROUND(SUM(OFF_TIME) / 60, 2) AS OFF_TIME,
             ROUND((SUM(SETUP_TIME) - SUM(OFF_SETUP_TIME)) / 60, 2) AS SETUP_TIME,
             ROUND(SUM(SLACK_TIME) / 60, 2) AS SLACK_TIME
           , 'MINUTE' AS capacity_uom
           , 0 AS plan_qty
           , @v_proc_name AS insert_id
           , getdate() AS insert_dttm
      FROM   (
              SELECT MASTER_ID, PLAN_ID, 
                     COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID,
                     LINE_ID, OPERATION_ID, WORK_CENTER_ID,
                     RESOURCE_ID, PLAN_DATE, CATEGORY, 
                     CASE WHEN RR = 1 AND CATEGORY = 'RUN' THEN DIFF ELSE 0 END RUN_TIME,
                     CASE WHEN RR = 2 AND CATEGORY = 'OFFTIME' THEN DIFF ELSE 0 END OFF_TIME,
                     CASE WHEN RR = 3 AND CATEGORY = 'SETUP' THEN DIFF ELSE 0 END SETUP_TIME,
                     CASE WHEN RR = 4 AND CATEGORY = 'SLACK' THEN DIFF ELSE 0 END SLACK_TIME,
                     CASE WHEN RR = 5 AND CATEGORY = 'OFF_SETUP' THEN DIFF ELSE 0 END OFF_SETUP_TIME
              FROM   (
                      SELECT A.*,
                             CONVERT(datetime2, dbo.fn_set_work_date2(master_id, plan_id, a.start_time, a.end_time), 112) AS plan_date,
                             DATEDIFF(SECOND, START_TIME, END_TIME) DIFF
                      FROM   (
                              SELECT A.MASTER_ID, A.PLAN_ID,
                                     A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.LINE_ID, A.OPERATION_ID, A.WORK_CENTER_ID,
                                     A.RESOURCE_ID, 
