      SET @n_log_count = @n_log_count + 1
      SET @sysdate = GETDATE()
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


      UPDATE SY_FP_PLAN_UTILIZATION_R
      SET    SY_FP_PLAN_UTILIZATION_R.PLAN_QTY = C.complete_qty
      FROM   SY_FP_PLAN_UTILIZATION_R A,
             (
              SELECT a.RESOURCE_ID
                   , CONVERT(datetime2, dbo.fn_set_work_date2(a.master_id, a.plan_id, a.START_TIME, a.END_TIME), 112) AS start_date
                   , ceiling(sum(a.COMPLETE_QTY)) AS complete_qty
              FROM   dbo.TH_BUF_OUT_WORK_ORDER_SPL  AS a
              WHERE  a.MASTER_ID = @v_master_id 
              AND    a.PLAN_ID = @v_plan_id 
              AND    a.OUT_VERSION_ID = @v_out_version_id
              GROUP BY a.RESOURCE_ID
                     , CONVERT(datetime2, dbo.fn_set_work_date2(a.master_id, a.plan_id, a.START_TIME, a.END_TIME), 112)
             )  AS c 
      WHERE  A.INSTANCE_ID = @v_master_id
      AND    A.FP_PLAN_ID = @v_plan_id
      AND    a.EQUIPMENT_ID = c.RESOURCE_ID 
      AND    CAST(CONVERT(nvarchar(8),a.PLAN_DATE, 112) AS DATETIME) = c.start_date             

      --LOG 생성
      SET @v_message = @@ROWCOUNT
      SET @n_log_count = @n_log_count + 1
      SET @sysdate = GETDATE()
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

